code_example.compute_shader:
// Particle update compute shader
#version 450
layout(local_size_x = 64) in;

layout(binding = 0) buffer ParticleBuffer {
  vec4 positions[];
  vec4 velocities[];
  float lifetimes[];
};

void main() {
  uint index = gl_GlobalInvocationID.x;
  if (index >= positions.length()) return;

  // Update position with velocity
  positions[index].xyz += velocities[index].xyz * dt;

  // Apply gravity
  velocities[index].y -= 9.81 * dt;

  // Update lifetime
  lifetimes[index] -= dt;
}

code_example.culling_system:
struct ParticleSystem {
  spatial_grid: SpatialGrid<ParticleChunk>,
  view_frustum: Frustum,

  fn update_visible_particles(&mut self) {
    let visible_chunks = self.spatial_grid
      .query_frustum(&self.view_frustum);

    for chunk in visible_chunks {
      chunk.update_particles();
    }
  }
}
